        row_output = output[r]

        for c in range(width):
            if grid[r][c] == bg:
                # Background cell
                if grid[r][0] == marker:
                    # Fill entire row except col 0 if marker
                    if c > 0 and row_output[c] == bg:
                        row_output[c] = fill
                elif any(s[0] == r and s[2] != marker for s in specials):
