    from collections import Counter

    all_vals = sum(grid, [])
    bg = max(set(all_vals), key=all_vals.count)

    corners = {}
    for name, pos in [('tl', (0,0)), ('tr', (0,width-1)), ('bl', (height-1,0)), ('br', (height-1,width-1))]:
