    if len(non_bg_corners) == 1:
        marker = non_bg_corners.popitem()[1]
    else:
        corner_counts = Counter(non_bg_corners.values())
        marker = corner_counts.most_common(1)[0][0]

    # Find all special cells (non-bg, non-marker)
    specials = [(r, c, grid[r][c]) for r in range(height) for c in range(width) 
                if grid[r][c] != bg and grid[r][c] != marker]

    if not specials:
        return grid  # No special cells, no fill

    special_vals = [v for r, c, v in specials]
    fill = max(special_vals)

    output = [row[:] for row in grid]

    for r in range(height):
